import java.io.BufferedReader
import java.io.InputStreamReader
import java.io.OutputStreamWriter
import java.io.BufferedWriter
import java.util.StringTokenizer

const val MOD = 998244353

fun modPow(a: Long, e: Long = MOD - 2): Long {
    var r = 1L
    var x = a % MOD
    var exp = e
    while (exp > 0) {
        if ((exp and 1) == 1L) r = r * x % MOD
        x = x * x % MOD
        exp = exp ushr 1
    }
    return r
}

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val bw = BufferedWriter(OutputStreamWriter(System.out))
    val st = StringTokenizer(br.readLine()!!)
    val n = st.nextToken().toInt()
    val k = st.nextToken().toInt()
    val l = st.nextToken().toLong() % MOD

    val maxN = 2 * n
    val fact = LongArray(maxN + 1)
    val invFact = LongArray(maxN + 1)
    fact[0] = 1
    for (i in 1..maxN) fact[i] = fact[i - 1] * i % MOD
    invFact[maxN] = modPow(fact[maxN])
    for (i in maxN downTo 1) invFact[i - 1] = invFact[i] * i % MOD

    fun C(nn: Int, kk: Int): Long {
        if (kk < 0 || kk > nn) return 0
        return fact[nn] * invFact[kk] % MOD * invFact[nn - kk] % MOD
    }

    // D array: D[d] = sum_{i=k..n} C(i, d) * C(n, i) * (-1)^{i+1}
    // We will compute S = sum_{d=k..n} D[d] * 2^d * (d!)^2 / (2d+1)!
    // Then answer = l * S mod MOD
    var S = 0L
    for (i in k..n) {
        val cn_i = C(n, i)
        val sign = if (i % 2 == 0) MOD - 1 else 1 // (-1)^{i+1}
        val coef = cn_i * sign % MOD
        for (d in k..i) {
            val term = coef * C(i, d) % MOD
            // multiply by 2^d * (d!)^2 / (2d+1)!
            val p2 = modPow(2, d.toLong())
            val num = fact[d] * fact[d] % MOD
            val den = fact[2 * d + 1]
            val frac = p2 * num % MOD * modPow(den) % MOD
            S = (S + term * frac) % MOD
        }
    }

    val ans = l * S % MOD
    bw.write(ans.toString())
    bw.newLine()
    bw.flush()
}
